sections.code:
def complete_task(tasks, task_id):
    for task in tasks:
        if task["id"] == task_id:
            task["done"] = True
            return True
    return False

def remove_task(tasks, task_id):
    for task in tasks:
        if task["id"] == task_id:
            tasks.remove(task)
            return True
    return False

tasks = [
    {"id": 1, "title": "Learn Python", "done": False},
    {"id": 2, "title": "Buy bread", "done": False},
    {"id": 3, "title": "Call mom", "done": False},
]
complete_task(tasks, 2)
print(complete_task(tasks, 9))
remove_task(tasks, 1)
done_count = sum(1 for task in tasks if task["done"])
print(f"Done: {done_count}/{len(tasks)}")
for task in tasks:
    mark = "x" if task["done"] else " "
    print(f"[{mark}] {task['id']}. {task['title']}")

